CREATE TABLE IF NOT EXISTS gis_identity_resolution_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, source_provider text NOT NULL, target_provider text NOT NULL, source_feature_count integer NOT NULL DEFAULT 0, target_feature_count integer NOT NULL DEFAULT 0, matched_count integer NOT NULL DEFAULT 0, ambiguous_count integer NOT NULL DEFAULT 0, unresolved_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Pending', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_identity_crosswalks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_identity_resolution_runs(id) ON DELETE CASCADE, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_provider text NOT NULL, target_provider_feature_id text, target_external_feature_id text, source_code text, source_name text, source_parent_code text, normalized_name text, candidate_score numeric(6,5) NOT NULL DEFAULT 0, match_method text NOT NULL, confidence text NOT NULL DEFAULT 'Unresolved', review_required boolean NOT NULL DEFAULT true, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_identity_run ON gis_identity_crosswalks(run_id,confidence,review_required);
CREATE INDEX IF NOT EXISTS idx_gis_identity_source ON gis_identity_crosswalks(source_feature_id);
CREATE INDEX IF NOT EXISTS idx_gis_identity_target ON gis_identity_crosswalks(target_provider,target_provider_feature_id);